app.get('/theme-banner/:theme.jpg', (req, res) => {
  const id = String(req.params.theme || '');
  // V104: temas 1 a 10 usam arquivos HD locais. Mantém fallback base64 para compatibilidade.
  const m = id.match(/^theme-(\d{1,2})$/);
  if (m) {
    const n = Number(m[1]);
    if (n >= 1 && n <= 10) {
      const file = path.join(__dirname, 'theme_hd', `theme-${n}.jpg`);
      try {
        if (fs.existsSync(file)) {
          res.setHeader('Content-Type', 'image/jpeg');
          res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
          res.setHeader('Pragma', 'no-cache');
          res.setHeader('Expires', '0');
          return res.sendFile(file);
        }
      } catch (_) {}
    }
  }
  const data = THEME_BANNERS_V100[id];
  if (!data) return res.status(404).end();
  res.setHeader('Content-Type', 'image/jpeg');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
  return res.end(Buffer.from(data, 'base64'));
});

