async function salvarArquivoTelegramEmEsim(msg) {
  if (!tgBot || !msg) return null;
  try {
    let fileId = null;
    let ext = '.jpg';
    if (Array.isArray(msg.photo) && msg.photo.length) {
      fileId = msg.photo[msg.photo.length - 1].file_id;
      ext = '.jpg';
    } else if (msg.document?.file_id) {
      fileId = msg.document.file_id;
      const nome = String(msg.document.file_name || '').toLowerCase();
      if (nome.endsWith('.png')) ext = '.png';
      else if (nome.endsWith('.webp')) ext = '.webp';
      else if (nome.endsWith('.pdf')) ext = '.pdf';
      else if (nome.endsWith('.jpg') || nome.endsWith('.jpeg')) ext = '.jpg';
    }
    if (!fileId) return null;
    const baixado = await tgBot.downloadFile(fileId, ESIM_DIR);
    const fileName = `esim_manual_tg_${Date.now()}_${Math.random().toString(16).slice(2)}${ext}`;
    const destino = path.join(ESIM_DIR, fileName);
    fs.renameSync(baixado, destino);
    return { fileName, filePath: destino, rel: `esim/${fileName}` };
  } catch (e) {
    console.log('❌ ERRO SALVAR ARQUIVO TELEGRAM:', e.message);
    return null;
  }
}
function adminsJids() { return ADMIN_TELEGRAM_ID ? [tgJid(ADMIN_TELEGRAM_ID)] : []; }
const COLUNA_AVISO_POR_TIPO = {
  NOVO_SERVICO: 'novos_servicos',
  ESIM: 'pedidos_esim',
  PAGAMENTO: 'pagamentos',
  FINALIZADO: 'finalizados',
  CANCELADO: 'cancelados'
};
async function enviarAvisoDestinatarios(tipo, texto) {
  const coluna = COLUNA_AVISO_POR_TIPO[String(tipo || 'NOVO_SERVICO').toUpperCase()];
  if (!coluna) return { total: 0, enviados: 0, falhas: 0 };
  const rows = await all(`SELECT * FROM destinatarios_avisos WHERE ativo=1 AND ${coluna}=1 ORDER BY id ASC`);
  let enviados = 0, falhas = 0;
  for (const d of rows) {
    let ok = false;
    try {
      if (d.canal === 'TELEGRAM') {
        if (!tgBot) throw new Error('Bot Telegram não conectado');
        await tgBot.sendMessage(String(d.destino), String(texto || ''), { parse_mode: 'Markdown' });
        ok = true;
      } else if (d.canal === 'WHATSAPP') {
        ok = await enviarTexto(`wa:${normalizarNumeroWhatsApp(d.destino)}`, String(texto || ''));
        if (!ok) throw new Error('WhatsApp de serviços não conectado ou envio recusado');
      }
      if (ok) enviados++;
      await run('UPDATE destinatarios_avisos SET ultimo_envio=CURRENT_TIMESTAMP, ultimo_status=?, atualizado_em=CURRENT_TIMESTAMP WHERE id=?', ['SUCESSO', d.id]);
    } catch (e) {
      falhas++;
      const detalhe = String(e.message || e).slice(0, 180);
      await run('UPDATE destinatarios_avisos SET ultimo_envio=CURRENT_TIMESTAMP, ultimo_status=?, atualizado_em=CURRENT_TIMESTAMP WHERE id=?', [`ERRO: ${detalhe}`, d.id]);
      console.log(`⚠️ Falha aviso ${d.nome}:`, detalhe);
    }
  }
  // Mantém o ADMIN_TELEGRAM_ID como emergência quando ele ainda não estiver cadastrado.
  const adminJaCadastrado = rows.some(d => d.canal === 'TELEGRAM' && String(d.destino) === String(ADMIN_TELEGRAM_ID));
  if (ADMIN_TELEGRAM_ID && tgBot && !adminJaCadastrado) {
    try { await tgBot.sendMessage(ADMIN_TELEGRAM_ID, String(texto || ''), { parse_mode: 'Markdown' }); enviados++; }
    catch (e) { falhas++; console.log('⚠️ Falha ao avisar admin Telegram:', e.message); }
  }
  return { total: rows.length + (ADMIN_TELEGRAM_ID && !adminJaCadastrado ? 1 : 0), enviados, falhas };
}
async function enviarParaAdmins(texto, tipo='NOVO_SERVICO') {
  return enviarAvisoDestinatarios(tipo, texto);
}
async function enviarMensagemRevendas({ texto, revendaId=null, imagemPath=null, enviarWhatsapp=true, enviarTelegram=true }) {
  const rows = revendaId
    ? await all('SELECT * FROM revendas WHERE id=? AND status="ATIVA"', [revendaId])
    : await all('SELECT * FROM revendas WHERE status="ATIVA"');
  let total = 0, enviadas = 0, falhas = 0;
  for (const r of rows) {
    if (enviarWhatsapp) {
      const jid = r.jid || numberToJid(r.whatsapp);
      if (jid) {
        total++;
        try {
          if (imagemPath) await enviarImagem(jid, imagemPath, texto);
          else await enviarTexto(jid, texto);
          enviadas++;
        } catch (e) { falhas++; console.log('⚠️ Falha mensagem WhatsApp:', r.id, e.message); }
        await new Promise(resolve => setTimeout(resolve, 350));
      }
    }
    if (enviarTelegram && r.telegram_id && tgBot) {
      total++;
      try {
        if (imagemPath && fs.existsSync(imagemPath)) await tgBot.sendPhoto(String(r.telegram_id), fs.createReadStream(imagemPath), { caption: texto });
        else await tgBot.sendMessage(String(r.telegram_id), texto);
        enviadas++;
      } catch (e) { falhas++; console.log('⚠️ Falha mensagem Telegram:', r.id, e.message); }
      await new Promise(resolve => setTimeout(resolve, 250));
    }
  }
  return { total, enviadas, falhas };
}
function caminhoImagemCampanha(imagemRel) {
  if (!imagemRel) return null;
  const raw = String(imagemRel).trim();
  // V111: campanhas antigas de grupos guardavam caminho absoluto em /data/ads-images.
  if (path.isAbsolute(raw)) return raw;
  const rel = raw.replace(/^\/+/, '');
  if (rel.startsWith('esim/')) return path.join(ESIM_DIR, path.basename(rel));
  if (rel.startsWith('ads-images/')) return path.join(DATA_DIR, rel);
  return path.join(PUBLIC_DIR, rel);
}

async function estoqueDisponivelCampanha(produtoId) {
  if (!produtoId) return null;
  const p = await get('SELECT nome_plano FROM esim_planos WHERE id=?', [produtoId]);
  if (!p) return 0;
  const q = await get("SELECT COUNT(*) qtd FROM esim_estoque WHERE nome_plano=? AND status='DISPONIVEL'", [p.nome_plano]);
  return Number(q?.qtd || 0);
}
function mensagemCampanhaVariada(campanha) {
  const base = String(campanha.mensagem || '');
  if (!Number(campanha.variar_texto || 0)) return base;
  const aberturas = ['🔥 Oferta disponível!', '🚀 Aproveite agora!', '📣 Novidade para você!', '⚡ Estoque disponível!', '✅ Produto liberado para compra!'];
  const n = Number(campanha.ciclos_enviados || campanha.total_envios || 0);
  return `${aberturas[n % aberturas.length]}\n\n${base}`;
}
async function enviarCampanhaAnuncio(campanha) {
  const clientes = await all(`SELECT id,nome,whatsapp,jid,telegram_id FROM revendas WHERE status='ATIVA' ORDER BY id ASC`);
  const imagemPath = caminhoImagemCampanha(campanha.imagem);
  const texto = mensagemCampanhaVariada(campanha);
  let total = 0, enviadas = 0, falhas = 0;
  const pausa = ms => new Promise(resolve => setTimeout(resolve, ms));
  const enviarClientes = Number(campanha.destino_clientes ?? 1) === 1;

  if (enviarClientes) {
    for (const cliente of clientes) {
      if (Number(campanha.enviar_whatsapp || 0) === 1) {
        const numero = normalizarNumeroWhatsApp(cliente.whatsapp || jidToNumber(cliente.jid || ''));
        if (numero) {
          total++;
          const ok = imagemPath && fs.existsSync(imagemPath)
            ? await enviarImagemWhatsApp(numero, imagemPath, texto)
            : await enviarWhatsAppTexto(numero, texto);
          if (ok) enviadas++; else falhas++;
          await pausa(500);
        }
      }
      if (Number(campanha.enviar_telegram || 0) === 1 && cliente.telegram_id) {
        total++;
        let ok = false;
        try {
          const opts = opcoesCompraTelegram(campanha);
          if (imagemPath && fs.existsSync(imagemPath)) await tgBot.sendPhoto(String(cliente.telegram_id), fs.createReadStream(imagemPath), { caption: texto, ...opts });
          else await tgBot.sendMessage(String(cliente.telegram_id), texto, opts);
          ok = true;
        } catch (e) { console.log('⚠️ CAMPANHA TG:', e.message); }
        if (ok) enviadas++; else falhas++;
        await pausa(350);
      }
    }
  }

  if (Number(campanha.destino_grupo || 0) === 1 && Number(campanha.enviar_telegram || 0) === 1 && tgBot) {
    const grupoId = await getConfig('telegram_grupo_canal', '');
    if (grupoId) {
      total++;
      try {
        const opts = opcoesCompraTelegram(campanha);
        if (imagemPath && fs.existsSync(imagemPath)) await tgBot.sendPhoto(String(grupoId), fs.createReadStream(imagemPath), { caption: texto, ...opts });
        else await tgBot.sendMessage(String(grupoId), texto, opts);
        enviadas++;
      } catch (e) { falhas++; console.log('⚠️ CAMPANHA GRUPO/CANAL:', e.message); }
    } else { total++; falhas++; }
  }
  return { total, enviadas, falhas };
}


// ======================= V108: CENTRAL ÚNICA DE ANÚNCIOS =======================
function gruposCampanhaCentral(campanha) {
  try {
    const a=JSON.parse(campanha.grupos_json||'[]');
    if(!Array.isArray(a)) return [];
    // V113: remove IDs repetidos para o mesmo grupo nunca receber duas vezes na mesma rodada.
    return [...new Set(a.filter(x=>String(x).endsWith('@g.us')).map(String))];
  } catch(_){ return []; }
}
function imagemCampanhaCentral(campanha) {
  const fp=caminhoImagemCampanha(campanha.imagem);
  return fp && fs.existsSync(fp) ? fp : null;
}
function opcoesCompraTelegram(campanha) {
  const servicoId = Number(campanha?.servico_id_compra || 0);
  const produtoId = Number(campanha?.produto_id || 0);
  if (servicoId) return { reply_markup: { inline_keyboard: [[{ text: '🛒 COMPRAR AGORA', callback_data: `servico_${servicoId}` }]] } };
  if (produtoId) return { reply_markup: { inline_keyboard: [[{ text: '🛒 COMPRAR AGORA', callback_data: `esim_${produtoId}` }]] } };
  return {};
}
function parseDestinoCompraAnuncio(valor) {
  const v = String(valor || '').trim();
  let m = v.match(/^produto:(\d+)$/); if (m) return { produtoId: Number(m[1]), servicoId: null };
  m = v.match(/^servico:(\d+)$/); if (m) return { produtoId: null, servicoId: Number(m[1]) };
  return { produtoId: null, servicoId: null };
}
async function enviarTelegramCentral(campanha, texto, imagemPath) {
  if (!tgBot) throw new Error('Bot do Telegram não está conectado.');
  const clientes=await all(`SELECT telegram_id FROM revendas WHERE status='ATIVA' AND telegram_id IS NOT NULL AND TRIM(telegram_id)<>''`);
  let total=0,enviadas=0,falhas=0;
  for(const r of clientes){
    total++;
    try{
      const opts = opcoesCompraTelegram(campanha);
      if(imagemPath) await tgBot.sendPhoto(String(r.telegram_id),fs.createReadStream(imagemPath),{caption:texto,...opts});
      else await tgBot.sendMessage(String(r.telegram_id),texto,opts);
      enviadas++;
    }catch(e){falhas++;console.log('⚠️ V108 TELEGRAM ANÚNCIO:',e.message);}
    await dormir(250);
  }
  return {total,enviadas,falhas};
}
async function enviarUmGrupoCentral(campanha, grupoId, texto, imagemPath){
  const sessao=await sessaoParaAnuncios();
  if(!sessao?.socket||!sessao.conectado) throw new Error('Nenhum WhatsApp habilitado para Anúncios em Grupos está conectado.');
  const imagemBuffer=imagemPath?fs.readFileSync(imagemPath):null;
  await sessao.socket.sendMessage(String(grupoId),imagemBuffer?{image:imagemBuffer,caption:texto}:{text:texto});
  return true;
}
async function enviarExtrasRodadaCentral(campanha,texto,imagemPath){
  let total=0,enviadas=0,falhas=0; const detalhes=[];
  // V115: ordem fixa de cada rodada: 1) WhatsApp Status 2) Telegram 3) Grupos.
  if(Number(campanha.destino_status_whatsapp||0)===1){
    try{const r=await publicarStatusWhatsApp({texto,imagemBuffer:imagemPath?fs.readFileSync(imagemPath):null});total+=r.enviados+r.falhas;enviadas+=r.enviados;falhas+=r.falhas;detalhes.push(`Status ${r.enviados} sessão(ões), audiência ${r.audiencia}`)}
    catch(e){falhas++;detalhes.push(`Status: ${e.message}`)}
  }
  if(Number(campanha.destino_telegram_central||0)===1){
    try{const r=await enviarTelegramCentral(campanha,texto,imagemPath);total+=r.total;enviadas+=r.enviadas;falhas+=r.falhas;detalhes.push(`Telegram ${r.enviadas}/${r.total}`)}
    catch(e){falhas++;detalhes.push(`Telegram: ${e.message}`)}
  }
  return {total,enviadas,falhas,detalhes};
}
async function enviarGruposCentral(campanha,texto,imagemPath){
  const sessao=await sessaoParaAnuncios();
  if(!sessao?.socket||!sessao.conectado) throw new Error('Nenhum WhatsApp habilitado para Anúncios em Grupos está conectado.');
  let grupos=gruposCampanhaCentral(campanha);
  if(!grupos.length){
    const todos=await listarGruposAnuncios(); grupos=todos.map(g=>g.id);
  }
  if(!grupos.length) throw new Error('Nenhum grupo do WhatsApp disponível.');
  const imagemBuffer=imagemPath?fs.readFileSync(imagemPath):null;
  let enviadas=0,falhas=0;
  // V112: o administrador digita um intervalo FIXO em minutos entre os grupos.
  const intervaloMinutos=Math.max(1,Math.min(1440,Number(campanha.intervalo_grupos_minutos||5)));
  for(let i=0;i<grupos.length;i++){
    try{ await sessao.socket.sendMessage(grupos[i],imagemBuffer?{image:imagemBuffer,caption:texto}:{text:texto}); enviadas++; }
    catch(e){falhas++;console.log('❌ V112 GRUPO:',grupos[i],e.message);}
    if(i<grupos.length-1) await dormir(intervaloMinutos*60*1000);
  }
  return {total:grupos.length,enviadas,falhas};
}
async function enviarAnuncioCentral(campanha){
  const texto=String(campanha.mensagem||'').trim();
  const imagemPath=imagemCampanhaCentral(campanha);
  const detalhes=[]; let total=0,enviadas=0,falhas=0;
  // V115: ordem fixa também no envio manual/imediato.
  if(Number(campanha.destino_status_whatsapp||0)===1){
    try{const r=await publicarStatusWhatsApp({texto,imagemBuffer:imagemPath?fs.readFileSync(imagemPath):null});total+=r.enviados+r.falhas;enviadas+=r.enviados;falhas+=r.falhas;detalhes.push(`Status ${r.enviados} sessão(ões), audiência ${r.audiencia}`)}
    catch(e){falhas++;detalhes.push(`Status: ${e.message}`)}
  }
  if(Number(campanha.destino_telegram_central||0)===1){
    try{const r=await enviarTelegramCentral(campanha,texto,imagemPath);total+=r.total;enviadas+=r.enviadas;falhas+=r.falhas;detalhes.push(`Telegram ${r.enviadas}/${r.total}`)}
    catch(e){falhas++;detalhes.push(`Telegram: ${e.message}`)}
  }
  if(Number(campanha.destino_grupos_whatsapp||0)===1){
    try{const r=await enviarGruposCentral(campanha,texto,imagemPath);total+=r.total;enviadas+=r.enviadas;falhas+=r.falhas;detalhes.push(`Grupos ${r.enviadas}/${r.total}`)}
    catch(e){falhas++;detalhes.push(`Grupos: ${e.message}`)}
  }
  if(!Number(campanha.destino_grupos_whatsapp||0)&&!Number(campanha.destino_status_whatsapp||0)&&!Number(campanha.destino_telegram_central||0)) throw new Error('Nenhum canal selecionado.');
  const canais=[Number(campanha.destino_grupos_whatsapp)?'Grupos':'',Number(campanha.destino_status_whatsapp)?'Status':'',Number(campanha.destino_telegram_central)?'Telegram':''].filter(Boolean).join(' + ');
  await run(`INSERT INTO historico_anuncios_central(campanha_id,nome,canais,total,enviadas,falhas,detalhes,status) VALUES(?,?,?,?,?,?,?,?)`,[campanha.id,campanha.nome,canais,total,enviadas,falhas,detalhes.join(' | '),falhas&&enviadas===0?'ERRO':'CONCLUIDO']);
  return {total,enviadas,falhas,detalhes:detalhes.join(' | '),canais};
}
function proximoAnuncioCentral(campanha){
  const modo=String(campanha.modo_envio||'').toUpperCase();
  if(modo==='RECORRENTE') return `datetime('now','+${Math.max(1,Number(campanha.recorrencia_horas||24))} hours')`;
  return null;
}
// V109: botão COMPRAR AGORA restaurado no Telegram
// V112: minutos fixos entre grupos + horas livres entre rodadas completas
// V113: cursor persistente por grupo + bloqueio definitivo do agendador legado
// V114: migração única + campanhas apagadas não voltam + endpoints legados bloqueados
// V115: ordem fixa de envio: Status -> Telegram -> Grupos
// ===================== FIM V112 CENTRAL ANÚNCIOS =====================

let anunciosWorkerExecutando = false;
let anunciosWorkerIniciado = false;
async function processarAnunciosAutomaticos() {
  if (anunciosWorkerExecutando) return;
  anunciosWorkerExecutando = true;
  try {
    const campanhas = await all(`SELECT * FROM campanhas_anuncios
      WHERE ativo=1 AND proximo_envio IS NOT NULL AND datetime(proximo_envio) <= datetime('now')
      ORDER BY id ASC`);
    for (const campanha of campanhas) {
      try {
        const modo=String(campanha.modo_envio||'').toUpperCase();
        const texto=String(campanha.mensagem||'').trim();
        const imagemPath=imagemCampanhaCentral(campanha);
        const usaGrupos=Number(campanha.destino_grupos_whatsapp||0)===1;

        if (usaGrupos) {
          let grupos=gruposCampanhaCentral(campanha);
          if(!grupos.length){
            const todos=await listarGruposAnuncios();
            grupos=[...new Set(todos.map(g=>String(g.id)).filter(x=>x.endsWith('@g.us')))];
          }
          if(!grupos.length) throw new Error('Nenhum grupo do WhatsApp disponível.');

          let indice=Math.max(0,Number(campanha.grupo_indice_atual||0));
          if(indice>=grupos.length) indice=0;
          let rodadaEnviadas=Math.max(0,Number(campanha.rodada_enviadas||0));
          let rodadaFalhas=Math.max(0,Number(campanha.rodada_falhas||0));
          let extrasFeitos=Number(campanha.rodada_extras_enviados||0)===1;
          const detalhes=[];

          // Telegram e Status saem uma única vez no começo da rodada.
          if(!extrasFeitos){
            const ex=await enviarExtrasRodadaCentral(campanha,texto,imagemPath);
            rodadaEnviadas+=ex.enviadas; rodadaFalhas+=ex.falhas;
            detalhes.push(...ex.detalhes);
            extrasFeitos=true;
            await run(`UPDATE campanhas_anuncios SET rodada_extras_enviados=1,rodada_enviadas=?,rodada_falhas=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[rodadaEnviadas,rodadaFalhas,campanha.id]);
          }

          const grupoId=grupos[indice];
          try{
            await enviarUmGrupoCentral(campanha,grupoId,texto,imagemPath);
            rodadaEnviadas++;
          }catch(e){
            rodadaFalhas++;
            console.log('❌ V113 GRUPO:',grupoId,e.message);
          }

          const proximoIndice=indice+1;
          if(proximoIndice<grupos.length){
            const minutos=Math.max(1,Math.min(1440,Number(campanha.intervalo_grupos_minutos||5)));
            await run(`UPDATE campanhas_anuncios SET grupo_indice_atual=?,rodada_enviadas=?,rodada_falhas=?,proximo_envio=datetime('now',?),ultima_detalhes=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[
              proximoIndice,rodadaEnviadas,rodadaFalhas,`+${minutos} minutes`,`Rodada em andamento: grupo ${proximoIndice}/${grupos.length} concluído. Próximo em ${minutos} min.`,campanha.id
            ]);
            continue;
          }

          // Último grupo: fecha a rodada e somente agora começa a contar as horas de repetição.
          const canais=['Grupos',Number(campanha.destino_status_whatsapp)?'Status':'',Number(campanha.destino_telegram_central)?'Telegram':''].filter(Boolean).join(' + ');
          const detalheFinal=[...detalhes,`Grupos ${grupos.length}/${grupos.length}`].join(' | ');
          await run(`INSERT INTO historico_anuncios_central(campanha_id,nome,canais,total,enviadas,falhas,detalhes,status) VALUES(?,?,?,?,?,?,?,?)`,[
            campanha.id,campanha.nome,canais,rodadaEnviadas+rodadaFalhas,rodadaEnviadas,rodadaFalhas,detalheFinal,rodadaFalhas&&rodadaEnviadas===0?'ERRO':'CONCLUIDO'
          ]);
          if(modo==='RECORRENTE'){
            const horas=Math.max(1,Number(campanha.recorrencia_horas||24));
            await run(`UPDATE campanhas_anuncios SET grupo_indice_atual=0,rodada_enviadas=0,rodada_falhas=0,rodada_extras_enviados=0,ultimo_envio=CURRENT_TIMESTAMP,proximo_envio=datetime('now',?),total_envios=total_envios+1,ciclos_enviados=ciclos_enviados+1,ultima_enviadas=?,ultima_falhas=?,ultima_detalhes=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[
              `+${horas} hours`,rodadaEnviadas,rodadaFalhas,`Rodada concluída. Próxima rodada em ${horas}h.`,campanha.id
            ]);
          }else{
            await run(`UPDATE campanhas_anuncios SET ativo=0,grupo_indice_atual=0,rodada_enviadas=0,rodada_falhas=0,rodada_extras_enviados=0,ultimo_envio=CURRENT_TIMESTAMP,proximo_envio=NULL,total_envios=total_envios+1,ciclos_enviados=ciclos_enviados+1,ultima_enviadas=?,ultima_falhas=?,ultima_detalhes=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[
              rodadaEnviadas,rodadaFalhas,'Rodada concluída.',campanha.id
            ]);
          }
          notificarPainel('mensagem','📣 Rodada concluída',`${campanha.nome}: ${rodadaEnviadas} enviados`);
          continue;
        }

        // Campanhas sem grupos continuam sendo enviadas de uma vez.
        const resultado = await enviarAnuncioCentral(campanha);
        if(modo==='RECORRENTE'){
          const horas=Math.max(1,Number(campanha.recorrencia_horas||24));
          await run(`UPDATE campanhas_anuncios SET ultimo_envio=CURRENT_TIMESTAMP,proximo_envio=datetime('now',?),total_envios=total_envios+1,ciclos_enviados=ciclos_enviados+1,ultima_enviadas=?,ultima_falhas=?,ultima_detalhes=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[`+${horas} hours`,resultado.enviadas,resultado.falhas,resultado.detalhes,campanha.id]);
        }else{
          await run(`UPDATE campanhas_anuncios SET ativo=0,ultimo_envio=CURRENT_TIMESTAMP,proximo_envio=NULL,total_envios=total_envios+1,ciclos_enviados=ciclos_enviados+1,ultima_enviadas=?,ultima_falhas=?,ultima_detalhes=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[resultado.enviadas,resultado.falhas,resultado.detalhes,campanha.id]);
        }
      } catch (e) {
        console.log('❌ V113 ANÚNCIO AUTOMÁTICO:', campanha.id, e.message);
        await run(`UPDATE campanhas_anuncios SET proximo_envio=datetime('now','+10 minutes'),ultima_falhas=ultima_falhas+1,ultima_detalhes=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?`,[e.message,campanha.id]);
      }
    }
  } finally { anunciosWorkerExecutando = false; }
}
function iniciarWorkerAnuncios() {
  if (anunciosWorkerIniciado) return;
  anunciosWorkerIniciado = true;
  setInterval(() => processarAnunciosAutomaticos().catch(e => console.log('❌ WORKER ANÚNCIOS:', e.message)), 60 * 1000);
  setTimeout(() => processarAnunciosAutomaticos().catch(e => console.log('❌ WORKER ANÚNCIOS:', e.message)), 8000);
}

